#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    string kthSmallestPath(vector<int>& destination, int k) {
        int v = destination[0], h = destination[1], n = v + h;
        vector<vector<long long>> c(n + 1, vector<long long>(n + 1));
        for (int i = 0; i <= n; ++i) {
            c[i][0] = c[i][i] = 1;
            for (int j = 1; j < i; ++j)
                c[i][j] = min(2000000000LL, c[i - 1][j - 1] + c[i - 1][j]);
        }
        string ans;
        while (h || v) {
            if (h == 0) { ans += 'V'; --v; continue; }
            if (v == 0) { ans += 'H'; --h; continue; }
            long long withH = c[h + v - 1][v];
            if (k <= withH) { ans += 'H'; --h; }
            else { ans += 'V'; k -= withH; --v; }
        }
        return ans;
    }
};
